import forge.ai.*;import forge.game.*;import forge.game.card.*;import forge.game.combat.*;import forge.game.keyword.*;import forge.game.phase.*;import forge.game.player.*;import forge.game.spellability.*;import forge.game.zone.*;import org.testng.Assert;import java.util.*;
public class MarchShieldHeldoutRegression extends CounterRescuePaymentRegression {
 int groups; void run(String profile,int mode,boolean baseline){Game g=initAndCreateThreePlayerGame();Player ai=g.getPlayers().get(1),enemy=g.getPlayers().get(0);System.setProperty("forge.ai.ggsPilotPlayer",ai.getName());for(Player p:g.getPlayers())fillLibrary(p,20);System.setProperty("dragonmind.strategyProfile",profile);int life=mode==1?5:mode==2?7:mode==3?6:5;ai.setLife(life,null);for(int i=0;i<10;i++)addCard("Island",ai);
 Card bayek=addCard("Carnage Tyrant",enemy);addCard("Fireshrieker",enemy).attachToEntity(bayek,null);Card ezio=addCard("Ezio Auditore da Firenze",enemy);addCard("Brotherhood Regalia",enemy).attachToEntity(ezio,null);
 Card ggs=addCard("Goro-Goro and Satoru",ai),hire=addCard(mode==1?"Hill Giant":"Grim Hireling",ai),satoru=addCard("Satoru Umezawa",ai);List<Card> shields=List.of(ggs,hire,satoru);for(Card c:List.of(bayek,ezio,ggs,hire,satoru)){c.setSickness(false);c.setTurnInZone(-1);}g.getAction().checkStateEffects(true);
 Assert.assertEquals(bayek.getNetCombatDamage(),7);Assert.assertTrue(bayek.hasKeyword(Keyword.TRAMPLE));Assert.assertTrue(bayek.hasKeyword(Keyword.DOUBLE_STRIKE));Assert.assertTrue(bayek.hasKeyword(Keyword.HEXPROOF));
 Combat combat=new Combat(enemy);combat.addAttacker(bayek,ai);combat.addAttacker(ezio,ai);combat.setBlocked(bayek,true);combat.setBlocked(ezio,false);for(Card c:shields)combat.addBlocker(bayek,c);g.getPhaseHandler().setCombat(combat);g.getPhaseHandler().devModeSet(PhaseType.COMBAT_DECLARE_BLOCKERS,enemy,false);Assert.assertTrue(CombatUtil.validateAttackers(combat));Assert.assertNull(CombatUtil.validateBlocks(combat,ai));combat.orderBlockersForDamageAssignment();combat.orderAttackersForDamageAssignment();
 Card march=addCardToZone("March of Swirling Mist",ai,ZoneType.Hand);var choice=((PlayerControllerAi)ai.getController()).getAi().chooseSpellAbilityToPlay();Assert.assertNotNull(choice);SpellAbility cast=choice.get(0);Assert.assertEquals(cast.getHostCard(),march);System.out.println("ACTUAL_CHOICE targets="+cast.getTargets()+" X="+cast.getXManaCostPaid());Assert.assertEquals(cast.getTargets().getTargetCards().size(),!baseline?1:4);Assert.assertFalse(cast.canTarget(bayek));for(Card c:cast.getTargets().getTargetCards())Assert.assertTrue(cast.canTarget(c));Assert.assertTrue(ComputerUtilCost.canPayCost(cast,ai,false));Assert.assertTrue(ComputerUtil.handlePlayingSpellAbility(ai,cast,null));drain(g);Assert.assertTrue(ezio.isPhasedOut());System.out.println("PAID lands="+ai.getLandsInPlay().stream().filter(Card::isTapped).count()+" shields="+shields.stream().map(Card::isPhasedOut).toList());
 combat.assignCombatDamage(true);combat.dealAssignedDamage();System.out.println("FIRST_STRIKE life="+ai.getLife());g.getAction().checkStateEffects(true);drain(g);if(ai.getLife()>0){combat.assignCombatDamage(false);combat.dealAssignedDamage();g.getAction().checkStateEffects(true);drain(g);}System.out.println("HELDOUT_SHIELD profile="+profile+" mode="+mode+" baseline="+baseline+" life="+ai.getLife());Assert.assertEquals(ai.getLife(),baseline?life-7:life-(mode==1?3:4));groups++;}
 public static void main(String[]args){if(args.length<2||!args[0].equals("--purpose")||!args[1].equals("heldout"))throw new IllegalArgumentException("Requires --purpose heldout");MarchShieldHeldoutRegression t=new MarchShieldHeldoutRegression();t.initializeModel();boolean baseline=Arrays.asList(args).contains("--baseline");for(int m=0;m<4;m++)t.run("BALANCED",m,baseline);System.out.println("Checks passed: "+t.groups);System.exit(0);}
}
